<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;use PHPUnit\Framework\TestCase;
require_once dirname(__DIR__,2).'/includes/financial_decisions.php';
final class FinancialDecisionsTest extends TestCase
{
 private function db():PDO{$p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec('PRAGMA foreign_keys=ON;CREATE TABLE treneri(id INTEGER PRIMARY KEY,aktivni INTEGER);CREATE TABLE staff_user_positions(trainer_id INTEGER,position_code TEXT);CREATE TABLE staff_superadmins(trainer_id INTEGER);INSERT INTO treneri VALUES(1,1),(2,1),(3,0);');$p->exec("INSERT INTO staff_user_positions VALUES(1,'finance_manager'),(2,'coach'),(3,'finance_manager')");foreach(['20261023070000_financial_decisions','20261022223000_accounting_exports']as$name){$m=require dirname(__DIR__,2).'/migrations/'.$name.'.php';$m['up']($p);self::assertTrue($m['verify']($p));}return$p;}
 private function input():array{return['title'=>'LOCALHOST sazba','kind'=>'rates','state'=>'pending','valid_from'=>'2026-01-01','valid_to'=>'2026-12-31','source_reference'=>'LOCALHOST vedení, zápis TEST-13','decision_text'=>'Syntetická pravidla; ne provozní schválení','original_location'=>'TEST šanon A','reason'=>'LOCALHOST záznam','confirmed'=>'1'];}
 private function rejects(callable $f):void{try{$f();self::fail('Expected rejection');}catch(\DomainException $e){self::assertNotSame('',$e->getMessage());}}
 public function testImmutableVersionAndStaleCorrection():void{$p=$this->db();$id=\financialDecisionRecord($p,1,$this->input());$before=\financialDecisionGet($p,$id);$input=$this->input();$input['replaces_id']=$id;$input['state']='confirmed';$new=\financialDecisionRecord($p,1,$input);self::assertSame($before,\financialDecisionGet($p,$id));self::assertSame($id,(int)\financialDecisionGet($p,$new)['replaces_id']);$this->rejects(fn()=>\financialDecisionRecord($p,1,$input));self::assertFalse($p->inTransaction());self::assertSame(2,(int)$p->query('SELECT COUNT(*) FROM financial_decisions')->fetchColumn());}
 public function testRevokedRoleAndMissingOriginalNeverCreateConfirmedDecision():void{$p=$this->db();foreach([2,3,999]as$actor)$this->rejects(fn()=>\financialDecisionRecord($p,$actor,$this->input()));$i=$this->input();$i['state']='confirmed';$i['original_location']='';$this->rejects(fn()=>\financialDecisionRecord($p,1,$i));$i=$this->input();$i['confirmed']='';$this->rejects(fn()=>\financialDecisionRecord($p,1,$i));$p->exec('DELETE FROM staff_user_positions WHERE trainer_id=1');$this->rejects(fn()=>\financialDecisionRecord($p,1,$this->input()));self::assertSame(0,(int)$p->query('SELECT COUNT(*) FROM financial_decisions')->fetchColumn());}
 public function testValidityAndReplacementTypeAreExplicit():void{$p=$this->db();$i=$this->input();$i['valid_to']='2025-12-31';$this->rejects(fn()=>\financialDecisionRecord($p,1,$i));$i=$this->input();$i['state']='withdrawn';$this->rejects(fn()=>\financialDecisionRecord($p,1,$i));$id=\financialDecisionRecord($p,1,$this->input());$i=$this->input();$i['replaces_id']=$id;$i['kind']='approval_rules';$this->rejects(fn()=>\financialDecisionRecord($p,1,$i));}
 public function testHandoverAppendOnlyAndDoesNotChangeArchiveOrPayment():void{$p=$this->db();$p->exec("INSERT INTO accounting_export_batches(id,request_key,request_sha256,period_from,period_to,revision,snapshot_at,scope_code,status,snapshot_json,snapshot_sha256,storage_key,archive_sha256,created_by,reason) VALUES(1,'TEST','hash','2026-01-01','2026-01-31',1,'2026-02-01','r13-r36','incomplete','{}','hash','private://accounting-exports/test.zip','hash',1,'LOCALHOST')");$before=\accountingExportGet($p,1);$this->rejects(fn()=>\accountingExportHandover($p,1,1,'accepted',0,'LOCALHOST not yet handed over',true));\accountingExportHandover($p,1,1,'handed_over',0,'LOCALHOST osobní předání účetní TEST',true);$id=(int)$p->lastInsertId();$this->rejects(fn()=>\accountingExportHandover($p,1,1,'accepted',0,'LOCALHOST stale',true));\accountingExportHandover($p,1,1,'returned',$id,'LOCALHOST chybí doklad',true);$id=(int)$p->lastInsertId();\accountingExportHandover($p,1,1,'handed_over',$id,'LOCALHOST doplnění',true);$id=(int)$p->lastInsertId();\accountingExportHandover($p,1,1,'accepted',$id,'LOCALHOST doložené převzetí',true);self::assertSame($before,\accountingExportGet($p,1));self::assertSame(4,(int)$p->query('SELECT COUNT(*) FROM accounting_export_events')->fetchColumn());$this->rejects(fn()=>\accountingExportHandover($p,2,1,'returned',4,'LOCALHOST unauthorized',true));}
}
